{
    out->HasResult = in->has_result();
    out->Result = {};
    if (out->HasResult) GRPC_TO_TURBOLINK(&(in->result()), &(out->Result));
    out->HasInventory = in->has_inventory();
    out->Inventory = {};
    if (out->HasInventory) GRPC_TO_TURBOLINK(&(in->inventory()), &(out->Inventory));
}

void TURBOLINK_TO_GRPC(const FGrpcNightfallV1GrantItemResponse* in, ::nightfall::v1::GrantItemResponse* out)
{
    if (in->HasResult) TURBOLINK_TO_GRPC(&(in->Result), out->mutable_result());
    else out->clear_result();
    if (in->HasInventory) TURBOLINK_TO_GRPC(&(in->Inventory), out->mutable_inventory());
    else out->clear_inventory();
}

